-- 시스템 기본 AI Provider (docs/ai-provider-ai3.md 13장)
--  1) TB_AI_STNG : Lexorma 전체의 AI 설정. 행은 하나뿐이다 (PK = 1, CK_AI_STNG_01) → 기본 Provider 가 둘이 될 수 없다.
--     BSC_AI_PRVDR_SN : 시스템 기본 AI 제공자 (비면 미지정). FK_AI_STNG_01 (NO ACTION) 이라 기본으로 지정된 Provider 는 지울 수 없다
--  2) 그 한 행을 미지정(null)으로 넣는다. 이미 등록된 Provider 가 있어도 기본으로 지정하지 않는다
--  3) 예제 (데이터 사전 단어·용어 → 물리 → 논리 → 매핑, FK·CHECK·논리 관계) : 프로젝트 LEXORMA 의 예제가 있을 때만 넣는다
-- 증분 마이그레이션 : 이미 적용된 V0~V8 은 고치지 않는다.

create table TB_AI_STNG (
    AI_STNG_SN bigint not null,
    BSC_AI_PRVDR_SN bigint,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_AI_STNG primary key (AI_STNG_SN),
    constraint CK_AI_STNG_01 check (AI_STNG_SN = 1),
    constraint FK_AI_STNG_01 foreign key (BSC_AI_PRVDR_SN) references TB_AI_PRVDR (AI_PRVDR_SN)
);

comment on table TB_AI_STNG is 'AI 설정';
comment on column TB_AI_STNG.AI_STNG_SN is 'AI 설정 일련번호';
comment on column TB_AI_STNG.BSC_AI_PRVDR_SN is '기본 AI 제공자 일련번호';
comment on column TB_AI_STNG.REG_DT is '등록 일시';
comment on column TB_AI_STNG.MDFCN_DT is '수정 일시';
comment on column TB_AI_STNG.RGTR_ID is '등록자 아이디';
comment on column TB_AI_STNG.MDFR_ID is '수정자 아이디';

insert into TB_AI_STNG(AI_STNG_SN, BSC_AI_PRVDR_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) values(1, null, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM');

-- ---------- 예제 : 데이터 사전 (새 단어 설정, 용어·용어 단어). 같은 이름이 이미 있으면 넣지 않는다 ----------
insert into TB_STD_WORD(STD_WORD_SN, PRJ_SN, ENCT_CYCL, WORD_NM, WORD_ENG_ABBR_NM, WORD_ENG_NM, WORD_EXPLN, FRMT_WORD_YN, DMN_CLSF_NM, ABBR_USE_YN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_WORD, 0, 1, '설정', 'STNG', 'Setting', '어떤 것을 새로 만들어 정해 둠. 시스템이 동작하는 방식을 정한 값.', false, null, true, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_PRJ p where p.PRJ_SN = 0 and not exists (select 1 from TB_STD_WORD where PRJ_SN = 0 and WORD_NM = '설정');
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM, 0, 1, 'AI_설정_일련번호', 'AI 설정 일련번호 (행이 하나뿐이라 1).', 'AI_STNG_SN', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '일련번호L' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = 'AI_설정_일련번호');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = 'AI' where t.PRJ_SN = 0 and t.TRM_NM = 'AI_설정_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '설정' where t.PRJ_SN = 0 and t.TRM_NM = 'AI_설정_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '일련번호' where t.PRJ_SN = 0 and t.TRM_NM = 'AI_설정_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM(STD_TRM_SN, PRJ_SN, ENCT_CYCL, TRM_NM, TRM_EXPLN, TRM_ENG_ABBR_NM, PBADMS_STD_CD_NM, JRSDC_INST_NM, STD_DMN_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM, 0, 1, '기본_AI_제공자_일련번호', '시스템 기본 AI 제공자 일련번호 (비면 미지정).', 'BSC_AI_PRVDR_SN', null, null, d.STD_DMN_SN, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_DMN d where d.PRJ_SN = 0 and d.DMN_NM = '일련번호L' and not exists (select 1 from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '기본_AI_제공자_일련번호');
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 1, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '기본' where t.PRJ_SN = 0 and t.TRM_NM = '기본_AI_제공자_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 1);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 2, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = 'AI' where t.PRJ_SN = 0 and t.TRM_NM = '기본_AI_제공자_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 2);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 3, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '제공자' where t.PRJ_SN = 0 and t.TRM_NM = '기본_AI_제공자_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 3);
insert into TB_STD_TRM_WORD(STD_TRM_WORD_SN, STD_TRM_SN, STD_WORD_SN, SORT_ORD, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_STD_TRM_WORD, t.STD_TRM_SN, w.STD_WORD_SN, 4, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_STD_TRM t join TB_STD_WORD w on w.PRJ_SN = 0 and w.WORD_NM = '일련번호' where t.PRJ_SN = 0 and t.TRM_NM = '기본_AI_제공자_일련번호' and not exists (select 1 from TB_STD_TRM_WORD x where x.STD_TRM_SN = t.STD_TRM_SN and x.SORT_ORD = 4);

-- ---------- 예제 : 물리 모델 (같은 이름이 이미 있으면 넣지 않는다) ----------
insert into TB_TBL(TBL_SN, PRJ_SN, SCHM_SN, TBL_NM, TBL_KORN_NM, TBL_EXPLN, MSTR_TBL_YN, SORT_ORD, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_TBL, 0, s.SCHM_SN, 'TB_AI_STNG', 'AI 설정', 'Lexorma 전체의 AI 설정 (행 하나). 시스템 기본 AI 제공자 (없으면 비어 있다). 시스템 관리자만 바꾼다', false, (select coalesce(max(SORT_ORD), 0) + 1 from TB_TBL where PRJ_SN = 0), true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_SCHM s where s.PRJ_SN = 0 and s.BSC_YN = true and not exists (select 1 from TB_TBL where PRJ_SN = 0 and TBL_NM = 'TB_AI_STNG');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_COL, 0, t.TBL_SN, 'TB_AI_STNG', 'AI_STNG_SN', 'AI 설정 일련번호', 'BIGINT', null, null, null, false, null, 1, false, null, true, false, true, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = 'AI_설정_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_STNG' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'AI_STNG_SN');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_COL, 0, t.TBL_SN, 'TB_AI_STNG', 'BSC_AI_PRVDR_SN', '기본 AI 제공자 일련번호', 'BIGINT', null, null, null, true, null, 2, false, null, false, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '기본_AI_제공자_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_STNG' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'BSC_AI_PRVDR_SN');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_COL, 0, t.TBL_SN, 'TB_AI_STNG', 'REG_DT', '등록 일시', 'TIMESTAMP', null, null, null, true, null, 3, false, null, false, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '등록_일시'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_STNG' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'REG_DT');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_COL, 0, t.TBL_SN, 'TB_AI_STNG', 'MDFCN_DT', '수정 일시', 'TIMESTAMP', null, null, null, true, null, 4, false, null, false, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정_일시'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_STNG' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'MDFCN_DT');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_COL, 0, t.TBL_SN, 'TB_AI_STNG', 'RGTR_ID', '등록자 아이디', 'VARCHAR', 255, null, null, true, null, 5, false, null, false, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '등록자_아이디'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_STNG' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'RGTR_ID');
insert into TB_COL(COL_SN, PRJ_SN, TBL_SN, TBL_NM, COL_NM, COL_EXPLN, DATA_TYPE_NM, MAX_LEN, DATA_PRCSN, DCPT_LEN, NULL_ALWNC_YN, BSC_VL, SORT_ORD, MSTR_DATA_YN, RFRNC_TBL_NM, ESNTL_YN, SNSTV_INFO_YN, PK_YN, UNQ_YN, IDX_YN, ENCPT_YN, APRV_YN, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_COL, 0, t.TBL_SN, 'TB_AI_STNG', 'MDFR_ID', '수정자 아이디', 'VARCHAR', 255, null, null, true, null, 6, false, null, false, false, false, false, false, false, true, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정자_아이디'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_STNG' and not exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'MDFR_ID');

-- ---------- 예제 : FK · CHECK (V6 과 같은 규칙 : 실제 제약 이름 그대로, 출처 USER·승인) ----------
insert into TB_TBL_REL(REL_SN, PRJ_SN, ORGNL_TBL_SN, TRGT_TBL_SN, REL_NM, REL_TYPE_CD, REL_SRC_CD, DRVN_COL_SN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_TBL_REL, 0, o.TBL_SN, t.TBL_SN, 'FK_AI_STNG_01', 'FK', 'USER', null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL o join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_PRVDR' where o.PRJ_SN = 0 and o.TBL_NM = 'TB_AI_STNG' and exists (select 1 from TB_COL c where c.TBL_SN = o.TBL_SN and c.COL_NM = 'BSC_AI_PRVDR_SN') and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'AI_PRVDR_SN') and not exists (select 1 from TB_TBL_REL r where r.PRJ_SN = 0 and r.ORGNL_TBL_SN = o.TBL_SN and upper(r.REL_NM) = 'FK_AI_STNG_01');
insert into TB_TBL_REL_COL(REL_COL_SN, REL_SN, ORGNL_COL_SN, TRGT_COL_SN, COL_ORD) select next value for SQ_TBL_REL_COL, r.REL_SN, oc.COL_SN, tc.COL_SN, 1 from TB_TBL_REL r join TB_TBL o on o.TBL_SN = r.ORGNL_TBL_SN and o.PRJ_SN = 0 and o.TBL_NM = 'TB_AI_STNG' join TB_COL oc on oc.TBL_SN = r.ORGNL_TBL_SN and oc.COL_NM = 'BSC_AI_PRVDR_SN' join TB_COL tc on tc.TBL_SN = r.TRGT_TBL_SN and tc.COL_NM = 'AI_PRVDR_SN' where r.PRJ_SN = 0 and upper(r.REL_NM) = 'FK_AI_STNG_01' and not exists (select 1 from TB_TBL_REL_COL x where x.REL_SN = r.REL_SN and x.COL_ORD = 1);
insert into TB_TBL_CNSTRT(CNSTRT_SN, PRJ_SN, TBL_SN, CNSTRT_NM, CNSTRT_TYPE_CD, INSP_EXPR_CN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_TBL_CNSTRT, 0, t.TBL_SN, 'CK_AI_STNG_01', 'CHECK', '(ai_stng_sn = 1)', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_STNG' and exists (select 1 from TB_COL c where c.TBL_SN = t.TBL_SN and c.COL_NM = 'AI_STNG_SN') and not exists (select 1 from TB_TBL_CNSTRT k where k.TBL_SN = t.TBL_SN and upper(k.CNSTRT_NM) = 'CK_AI_STNG_01');
insert into TB_TBL_CNSTRT_COL(CNSTRT_COL_SN, CNSTRT_SN, COL_SN, COL_ORD) select next value for SQ_TBL_CNSTRT_COL, k.CNSTRT_SN, c.COL_SN, 1 from TB_TBL_CNSTRT k join TB_TBL t on t.TBL_SN = k.TBL_SN and t.PRJ_SN = 0 and t.TBL_NM = 'TB_AI_STNG' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'AI_STNG_SN' where upper(k.CNSTRT_NM) = 'CK_AI_STNG_01' and not exists (select 1 from TB_TBL_CNSTRT_COL x where x.CNSTRT_SN = k.CNSTRT_SN and x.COL_ORD = 1);

-- ---------- 예제 : 논리 모델 (엔터티 = 테이블 한글명, 속성 = 컬럼의 용어). LEXORMA 논리 모델이 있을 때만 ----------
insert into TB_LGCL_ENTT(LGCL_ENTT_SN, PRJ_SN, LGCL_MDL_SN, ENTT_NM, ENTT_EXPLN, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_ENTT, 0, m.LGCL_MDL_SN, 'AI 설정', 'Lexorma 전체의 AI 설정 (행 하나). 시스템 기본 AI 제공자 (없으면 비어 있다). 시스템 관리자만 바꾼다', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_MDL m where m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA' and not exists (select 1 from TB_LGCL_ENTT e where e.LGCL_MDL_SN = m.LGCL_MDL_SN and e.ENTT_NM = 'AI 설정');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_ATRB, e.LGCL_ENTT_SN, 'AI 설정 일련번호', null, null, true, 1, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = 'AI_설정_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = 'AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = 'AI 설정 일련번호');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_ATRB, e.LGCL_ENTT_SN, '기본 AI 제공자 일련번호', null, null, false, 2, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '기본_AI_제공자_일련번호'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = 'AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '기본 AI 제공자 일련번호');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_ATRB, e.LGCL_ENTT_SN, '등록 일시', null, null, false, 3, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '등록_일시'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = 'AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '등록 일시');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_ATRB, e.LGCL_ENTT_SN, '수정 일시', null, null, false, 4, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정_일시'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = 'AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '수정 일시');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_ATRB, e.LGCL_ENTT_SN, '등록자 아이디', null, null, false, 5, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '등록자_아이디'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = 'AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '등록자 아이디');
insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_ATRB, e.LGCL_ENTT_SN, '수정자 아이디', null, null, false, 6, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정자_아이디'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = 'AI 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '수정자 아이디');
insert into TB_LGCL_IDNTFR(LGCL_IDNTFR_SN, LGCL_ENTT_SN, IDNTFR_NM, BSC_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_IDNTFR, e.LGCL_ENTT_SN, 'AI 설정 식별자', true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = 'AI 설정' and not exists (select 1 from TB_LGCL_IDNTFR i where i.LGCL_ENTT_SN = e.LGCL_ENTT_SN and i.BSC_YN = true);
insert into TB_LGCL_IDNTFR_ATRB(LGCL_IDNTFR_ATRB_SN, LGCL_IDNTFR_SN, LGCL_ATRB_SN, SORT_ORD) select next value for SQ_LGCL_IDNTFR_ATRB, i.LGCL_IDNTFR_SN, a.LGCL_ATRB_SN, 1 from TB_LGCL_IDNTFR i join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = i.LGCL_ENTT_SN and a.ATRB_NM = 'AI 설정 일련번호' where i.LGCL_ENTT_SN = (select LGCL_ENTT_SN from TB_LGCL_ENTT where LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ENTT_NM = 'AI 설정') and i.IDNTFR_NM = 'AI 설정 식별자' and not exists (select 1 from TB_LGCL_IDNTFR_ATRB x where x.LGCL_IDNTFR_SN = i.LGCL_IDNTFR_SN);

-- ---------- 예제 : 논리 관계 (V6 과 같은 규칙 : 상위 AI 제공자 → 하위 AI 설정, 이름 = 상위 엔터티명, FK 컬럼이 PK 가 아니라 비식별, NULL 허용이라 상위 최소 0) ----------
insert into TB_LGCL_REL(LGCL_REL_SN, PRJ_SN, LGCL_MDL_SN, ORGNL_ENTT_SN, TRGT_ENTT_SN, REL_NM, REL_EXPLN, IDNTF_YN, ORGNL_MIN_CNT, ORGNL_MAX_CNT, TRGT_MIN_CNT, TRGT_MAX_CNT, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_REL, 0, pe.LGCL_MDL_SN, pe.LGCL_ENTT_SN, ce.LGCL_ENTT_SN, pt.TBL_KORN_NM, ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'BSC_AI_PRVDR_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조', case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('BSC_AI_PRVDR_SN') and c.PK_YN = false) then false else true end, case when exists (select 1 from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM in ('BSC_AI_PRVDR_SN') and c.NULL_ALWNC_YN = true) then 0 else 1 end, 1, 0, null, true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL ct join TB_TBL pt on pt.PRJ_SN = 0 and pt.TBL_NM = 'TB_AI_PRVDR' join TB_LGCL_ENTT ce on ce.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and ce.ENTT_NM = ct.TBL_KORN_NM join TB_LGCL_ENTT pe on pe.LGCL_MDL_SN = ce.LGCL_MDL_SN and pe.ENTT_NM = pt.TBL_KORN_NM where ct.PRJ_SN = 0 and ct.TBL_NM = 'TB_AI_STNG' and not exists (select 1 from TB_LGCL_REL x where x.LGCL_MDL_SN = ce.LGCL_MDL_SN and x.ORGNL_ENTT_SN = pe.LGCL_ENTT_SN and x.TRGT_ENTT_SN = ce.LGCL_ENTT_SN and x.REL_EXPLN = ct.TBL_KORN_NM || '의 ' || (select c.COL_EXPLN from TB_COL c where c.TBL_SN = ct.TBL_SN and c.COL_NM = 'BSC_AI_PRVDR_SN') || ' 로 ' || pt.TBL_KORN_NM || ' 을(를) 참조');

-- ---------- 예제 : 논리 ↔ 물리 매핑 (V2~V8 과 같은 규칙 : 새 엔터티·속성만 이어진다) ----------
insert into TB_ENTT_TBL_MPNG(ENTT_TBL_MPNG_SN, PRJ_SN, LGCL_ENTT_SN, TBL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select next value for SQ_ENTT_TBL_MPNG, 0, e.LGCL_ENTT_SN, t.TBL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_LGCL_ENTT e
join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA'
join TB_TBL t on t.PRJ_SN = 0 and t.TBL_KORN_NM = e.ENTT_NM
where e.PRJ_SN = 0
  and (select count(*) from TB_TBL t2 where t2.PRJ_SN = 0 and t2.TBL_KORN_NM = e.ENTT_NM) = 1
  and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.LGCL_ENTT_SN = e.LGCL_ENTT_SN)
  and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.TBL_SN = t.TBL_SN);
insert into TB_ATRB_COL_MPNG(ATRB_COL_MPNG_SN, ENTT_TBL_MPNG_SN, LGCL_ATRB_SN, COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID)
select next value for SQ_ATRB_COL_MPNG, mp.ENTT_TBL_MPNG_SN, a.LGCL_ATRB_SN, c.COL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM'
from TB_ENTT_TBL_MPNG mp
join TB_LGCL_ENTT e on e.LGCL_ENTT_SN = mp.LGCL_ENTT_SN
join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA'
join TB_TBL t on t.TBL_SN = mp.TBL_SN and t.TBL_KORN_NM = e.ENTT_NM
join TB_LGCL_ATRB a on a.LGCL_ENTT_SN = e.LGCL_ENTT_SN
join TB_COL c on c.TBL_SN = t.TBL_SN and c.STD_TRM_SN = a.STD_TRM_SN
where mp.PRJ_SN = 0
  and (select count(*) from TB_LGCL_ATRB a2 where a2.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a2.STD_TRM_SN = a.STD_TRM_SN) = 1
  and (select count(*) from TB_COL c2 where c2.TBL_SN = t.TBL_SN and c2.STD_TRM_SN = a.STD_TRM_SN) = 1
  and not exists (select 1 from TB_ATRB_COL_MPNG x where x.LGCL_ATRB_SN = a.LGCL_ATRB_SN)
  and not exists (select 1 from TB_ATRB_COL_MPNG x where x.COL_SN = c.COL_SN);
